    funcao = 'n8n_assistente_desbloquear_horario'; args = { ...base, p_dia: ou(v('data')), p_inicio: ou(v('hora_inicio')) };
    break;
  case 'ver_bloqueios_horario':
    funcao = 'n8n_assistente_ver_bloqueios_horario'; args = { ...base, p_dia: ou(v('data')) };
