const NL = String.fromCharCode(10);
const a = m.args || {};
const links = [].concat($('Google: config').first().json.config?.loja?.google_agenda_ics || []).filter(Boolean);
if (!links.length) return [{ json: { texto: '' } }];
const respostas = $input.all().map((i) => i.json);
const dataTxt = String(a.p_data || a.p_inicio || '').slice(0, 10);
const dia = dataTxt ? DateTime.fromISO(dataTxt, { zone: 'America/Cuiaba' }) : DateTime.now().setZone('America/Cuiaba');
if (!respostas.every((r) => typeof r.data === 'string' && r.data.includes('BEGIN:VCALENDAR')))
  return [{ json: { texto: NL + NL + 'ATENÇÃO: não consegui ler a Google Agenda da dona agora. O resultado acima é só da agenda do app: avise que pode ter cliente marcada na Google que você não está vendo.' } }];
const ini = dia.startOf('day'), fim = ini.plus({ days: 1 });
const eventos = respostas.flatMap((r) => lerIcs(r.data)).filter(([x, y]) => x < fim && y > ini).sort((p, q) => p[0] - q[0]);
const hh = (d) => d.toFormat('HH:mm');
const lista = eventos.map(([x, y, t, todo]) => '- ' + (todo ? 'dia inteiro' : hh(x) + ' às ' + hh(y)) + ': ' + t).join(NL);
// minutos do dia ocupados na Google (a Resposta tira de horarios_livres o que encavala)
const ocupados = eventos.map(([x, y]) => [Math.max(0, x.diff(ini, 'minutes').minutes), Math.min(1440, y.diff(ini, 'minutes').minutes)]);
return [{ json: { ocupados, texto: NL + NL + 'GOOGLE AGENDA DA DONA em ' + ini.setLocale('pt-BR').toFormat('cccc, dd/LL') + ' (clientes que ainda não estão no app; conta como ocupado, junto com o app):' + NL +
  (lista || '- nada marcado na Google neste dia') + NL +
  'Não diga que um horário está livre olhando só o app: confira esta lista. Não marque nem ofereça horário que bata com ela sem a dona confirmar.' } }];

const m = $('Montar chamada').first().json;
let cfg = {}; try { cfg = $('Endereço: cadastro').first().json.config || {}; } catch (e) {}
const t = (v) => (typeof v === 'string' ? v.trim() : '');
const end = t(cfg.endereco), mapa = t((cfg.loja || {}).mapa);
const norm = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/\s+/g, ' ');
const txt = String((m.args && m.args.p_texto) || '');
let bloqueio = '';
if (m.enviar && txt) {
  const n = norm(txt);
  const rua = norm(end.split(',')[0] || '');            // "rua dos angicos"
  const numero = (end.match(/\d+/) || [''])[0];        // "690"
  const falaDeRua = /(^|[^a-z])(rua|r\.|avenida|av\.?|travessa|alameda|rodovia|estrada|pra[cç]a)\s+[a-z0-9]/.test(n);
  const ruaErrada = falaDeRua && (!rua || !n.includes(rua) || (numero && !n.includes(numero)));
  const links = txt.match(/(https?:\/\/|www\.)\S+|\S*(goo\.gl|maps\.|waze\.)\S*/gi) || [];
  const deMapa = (l) => /goo\.gl|maps|waze|localiza/i.test(l);
  const linkErrado = links.some((l) => deMapa(l) && (!mapa || !norm(mapa).includes(norm(l.replace(/[).,;!]+$/, '')).replace(/^https?:\/\//, ''))));
  const enfeite = /\[\s*(link|mapa|localiza)[^\]]*\]/i.test(txt);
  if (ruaErrada || linkErrado || enfeite) {
    bloqueio = 'NÃO ENVIADO (nada chegou à cliente): o texto tem ' + (ruaErrada ? 'um endereço que não é o do cadastro do salão' : 'um link de mapa que não existe no cadastro do salão') + '. ' +
      (end ? 'O ÚNICO endereço que vale é: ' + end + (mapa ? ' | mapa: ' + mapa : ' (não há link de mapa cadastrado: não mande link nenhum)') + '. Reescreva o texto com esse endereço, exatamente assim, e mande de novo agora.'
           : 'Não há endereço cadastrado no app: não mande endereço. Diga à dona que falta preencher o endereço em Dados do salão.');
  }
}
return [{ json: { ...m, bloqueio } }];

const TZ = 'America/Cuiaba';
const agora = DateTime.now().setZone(TZ);
let b = {}; try { b = JSON.parse($('Executar no banco').first().json.data || '{}'); } catch (e) {}
const txt = String(b.mensagem || '');
const tel = String(b.telefone || '').replace(/\D/g, '');
const falhou = (x) => !x || x.error || (x.code && x.message);
const lerTudo = (nome) => { try { return $(nome).all().map((i) => i.json); } catch (e) { return [{ error: 'não rodou' }]; } };
const rMsgs = lerTudo('Envio: conversa da cliente'), rAgs = lerTudo('Envio: horários da cliente');
const leuMsgs = !rMsgs.some((x) => x && (x.error || (x.code && x.message)));
const leuAgs = !rAgs.some((x) => x && (x.error || (x.code && x.message)));
const msgs = rMsgs.filter((x) => x && x.criado_em && !falhou(x));
const ags = rAgs.filter((x) => x && x.inicio && !falhou(x));
const hm = (s) => DateTime.fromISO(s).setZone(TZ).toFormat('HH:mm');
const norm = (s) => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
const n = norm(txt);
let bloqueio = '', recado = false;

// 4. vazio
if (!/[a-z0-9]/.test(n)) bloqueio = 'NÃO ENVIADO (nada chegou à cliente): o texto estava vazio. Escreva a mensagem e mande de novo.';

// 1. ela está conversando com a IA de atendimento agora
const ultimaDela = msgs.find((x) => x.direcao === 'entrada');
const minDela = ultimaDela ? agora.diff(DateTime.fromISO(ultimaDela.criado_em), 'minutes').minutes : 1e9;
const falaDeHorario = /\b\d{1,2} ?(h\b|h\d{2}|:\d{2}|horas?\b)|amanha|\bhoje\b|segunda|terca|quarta|quinta|sexta|sabado|domingo|\bdia \d|\b\d{1,2}\/\d{1,2}\b|horario|agenda|\bvaga|marcar|remarc|reagend|reserv|encaix/.test(n);
if (!bloqueio && leuMsgs && minDela <= 4 && falaDeHorario) {
  recado = true;
  bloqueio = 'GUARDEI COMO RECADO (nada foi mandado à cliente agora): ela está conversando com a IA de atendimento neste momento (última mensagem dela às ' + hm(ultimaDela.criado_em) + '). ' +
    'Se eu mandasse, ela receberia duas conversas ao mesmo tempo com ofertas diferentes. O seu texto foi passado para a IA de atendimento, que vai usar na próxima resposta a ela. ' +
    'Diga à Caroline em UMA linha: "*Nome* está conversando com a IA agora; passei seu recado pra IA usar na resposta ✅". NÃO chame chamar_cliente nem avisar_cliente de novo para ela agora e não diga que mandou.';
}

// 2. confirmação repetida
const ehConfirmacao = (s) => /confirm(ar|ando|ad[oa]|amos|o\b|ei)|lembrando (do|que|seu)|lembrete/.test(s) && /horario|amanha|\bhoje\b|atendimento/.test(s);
const ehMudanca = /\bmud|remarc|reagend|\btroc|passou para|passamos para|em vez de|novo horario|cancel|desmarc/.test(n);
if (!bloqueio && leuMsgs && ehConfirmacao(n) && !ehMudanca) {
  const ant = msgs.find((x) => x.direcao === 'saida' && ehConfirmacao(norm(x.conteudo)) && agora.diff(DateTime.fromISO(x.criado_em), 'hours').hours < 20);
  if (ant) {
    const resp = msgs.filter((x) => x.direcao === 'entrada' && x.criado_em > ant.criado_em).pop();
    bloqueio = 'NÃO ENVIADO (nada chegou à cliente): ela já recebeu confirmação deste horário às ' + hm(ant.criado_em) + ' («' + String(ant.conteudo).replace(/\s+/g, ' ').slice(0, 140) + '»)' +
      (resp ? ' e respondeu às ' + hm(resp.criado_em) + ': «' + String(resp.conteudo).replace(/\s+/g, ' ').slice(0, 100) + '»' : ' e ainda não respondeu') +
      '. A Caroline quer UMA confirmação por cliente: não mande outra. Conte a ela em uma linha se a cliente já confirmou ou não.';
  }
}

// 3. diz que está marcado/confirmado sem horário no app (ou com a data errada)
const afirma = /\b(confirmad[oa]s?|confirmadissim[oa]|marcad[oa]s?|reservad[oa]s?|agendad[oa]s?|garantid[oa]s?|marquei|reservei|agendei)\b/.test(n) && !/cancel|desmarc/.test(n);
if (!bloqueio && leuAgs && afirma) {
  const lista = ags.map((a) => DateTime.fromISO(a.inicio).setZone(TZ).toFormat("dd/LL 'às' HH:mm") + (a.servicos && a.servicos.nome ? ' (' + a.servicos.nome + ')' : '')).join('; ');
  if (!ags.length) {
    bloqueio = 'NÃO ENVIADO (nada chegou à cliente): o texto diz que o horário está marcado/confirmado/reservado, mas ela NÃO tem nenhum horário futuro no app. ' +
      'Primeiro grave com marcar_horario (dia, hora e serviço) e veja que voltou OK; só depois avise. Se a Caroline só quer oferecer, escreva como oferta, sem dizer que está marcado.';
  } else {
    const dias = new Set(ags.map((a) => DateTime.fromISO(a.inicio).setZone(TZ).toFormat('dd/LL')));
    const citadas = [...n.matchAll(/\b(\d{1,2})\/(\d{1,2})\b/g)].map((x) => x[1].padStart(2, '0') + '/' + x[2].padStart(2, '0'));
    if (citadas.length && citadas.every((d) => !dias.has(d))) {
      bloqueio = 'NÃO ENVIADO (nada chegou à cliente): o texto fala de ' + [...new Set(citadas)].join(', ') + ', mas os horários dela no app são: ' + lista +
        '. Confira o dia e o MÊS (em 13/11 uma cliente foi avisada de 17/12 quando o horário era 17/11) e mande de novo com a data certa.';
    }
  }
}
// 5. assistente-consertos.js (20/11, Vanessa): texto parecido com o que o salão mandou a ela nos últimos 10 min.
// "Parecido" = texto igual, ou o MESMO horário/dia citado e pelo menos 2 palavras do assunto em comum (sem contar nome, dia e palavras de horário)
// (as duas desculpas da Vanessa falavam de "14:30 amanhã"; uma oferta nova de "10h" passa).
const COMUNS_ENV = new Set('oi ola tudo bem bom dia boa tarde noite para voce voces pode como mais pelo pela com que nao sim esta ta fica ficar caroline horario horarios amanha hoje segunda terca quarta quinta sexta sabado domingo pediu pedir manha tarde'.split(' '));
// nome próprio (palavra com maiúscula fora do começo da frase, como o nome da cliente) também não conta como assunto
const nomes = (s) => new Set([...String(s || '').matchAll(/(?<![.!?]\s)(?<!^)\b([A-ZÀ-Ú][a-zà-ú]+)/g)].map((m) => norm(m[1])));
const palavras = (s) => { const nm = nomes(s); return new Set(norm(s).replace(/[^a-z0-9 ]+/g, ' ').split(/\s+/).filter((w) => w.length > 3 && !COMUNS_ENV.has(w) && !nm.has(w))); };
const marcas = (s) => new Set([...norm(s).matchAll(/\b(\d{1,2})(?:h|:)(\d{2})?\b|\b(\d{1,2})\/(\d{1,2})\b/g)].map((m) => m[1] !== undefined ? m[1] + ':' + (m[2] || '00') : m[3] + '/' + m[4]));
const igualTxt = (s) => norm(s).replace(/[^a-z0-9]+/g, ' ').trim();
if (!bloqueio && leuMsgs) {
  const novas = palavras(txt), horasNovas = marcas(txt);
  const recente = msgs.find((x) => x.direcao === 'saida' && agora.diff(DateTime.fromISO(x.criado_em), 'minutes').minutes <= 10 && (() => {
    if (igualTxt(x.conteudo) === igualTxt(txt)) return true;
    const velhas = palavras(x.conteudo), horasVelhas = marcas(x.conteudo);
    let comuns = 0; for (const w of novas) if (velhas.has(w)) comuns++;
    const mesmaHora = [...horasNovas].some((h) => horasVelhas.has(h));
    return mesmaHora && comuns >= 2;
  })());
  if (recente) {
    bloqueio = 'NÃO ENVIADO (nada chegou à cliente): às ' + hm(recente.criado_em) + ' ela já recebeu uma mensagem parecida: «' + String(recente.conteudo).replace(/\s+/g, ' ').slice(0, 160) + '». ' +
      'Duas mensagens quase iguais em poucos minutos confundem a cliente. Se a Caroline quer acrescentar algo, mande SÓ o que é novo, curto; se não há nada novo, não mande e conte isso à Caroline em uma linha.';
  }
}
// 6. assistente-consertos.js (PDF erro 12): fala de teste/sistema/IA ou emoji de enfeite não chega à cliente;
// volta para a assistente escrever do jeito da Caroline (prompt-assistente, seção G).
const robo = /fase de teste|em teste|estamos testando|\bsistema\b|\brobo\b|intelig[eê]ncia artificial|\bsou (a|uma) (ia|assistente)|assistente virtual|confirmad[ií]ssim/i.test(txt);
const enfeite = /[\u2728\u{1F485}\u{1F60A}\u2764\u2705\u{1F496}\u{1F497}\u{1F338}\u{1F31F}]/u.test(txt);
if (!bloqueio && (robo || enfeite)) {
  bloqueio = 'NÃO ENVIADO (nada chegou à cliente): ' + (robo ? 'o texto fala de teste, sistema, IA/assistente ou "confirmadíssimo"' : 'o texto tem emoji de enfeite (✨ 💅 😊 ❤️ ✅)') +
    ', e a cliente lê como se fosse a Caroline. Reescreva curto, do jeito dela (seção G: "Oi Ana, ficou sexta às 14h 🙏"), e mande de novo.';
}
return [{ json: { bloqueio, recado, telefone: tel, chave: tel.replace(/^(55\d\d)9(\d{8})$/, '$1$2'), texto: txt } }];

const ant = String($input.first().json.anterior || '').trim();
const novo = '[' + DateTime.now().setZone('America/Cuiaba').toFormat('HH:mm') + '] ' + String($('Envio: conferir').first().json.texto || '').trim();
return [{ json: { valor: ((ant ? ant + '\n' : '') + novo).slice(-1500) } }];
